std::string array(const std::vector<std::string>& rows){std::ostringstream o;o<<'[';for(std::size_t i=0;i<rows.size();++i)o<<(i?",":"")<<rows[i];o<<']';return o.str();}
std::string hex(const uint8_t* bytes,std::size_t n){std::string s;for(std::size_t i=0;i<n;++i){s.push_back("0123456789abcdef"[bytes[i]>>4]);s.push_back("0123456789abcdef"[bytes[i]&15]);}return s;}
